--genAI film review dataset for lab purposes only

DROP TABLE IF EXISTS film_reviews;

CREATE TABLE film_reviews (
    film_id       INTEGER PRIMARY KEY,
    film_title    VARCHAR(200) NOT NULL,
    release_date  DATE         NOT NULL,
    rating        NUMERIC(3,1) NOT NULL CHECK (rating BETWEEN 0 AND 10),
    review        TEXT         NOT NULL
);

INSERT INTO film_reviews (film_id, film_title, release_date, rating, review) VALUES
(1,  'Groundhog Day', '1993-02-12', 9.0,
 'A cynical weatherman relives the same day until he becomes a better person. Bill Murray is perfect, balancing sarcasm and sincerity, and the script turns a gimmick into a surprisingly moving meditation on growth.'),
(2,  'Lost in Translation', '2003-09-12', 8.5,
 'Two lonely strangers connect in neon-lit Tokyo. Murray gives a quiet, wry, deeply human performance opposite Scarlett Johansson. Sofia Coppola favours mood over plot, and the ambiguous ending lingers long afterwards.'),
(3,  'Ghostbusters', '1984-06-08', 8.0,
 'Three parapsychologists start a ghost-catching business in New York. Murray''s deadpan ad-libbing steals every scene, and the mix of comedy, spectacle and a great theme tune makes it endlessly rewatchable.'),
(4,  'Rushmore', '1998-12-11', 8.3,
 'An eccentric teenager and a melancholy industrialist fall for the same teacher. Wes Anderson''s quirky comedy has real heart, and Murray''s weary, understated turn revitalised his career.'),
(5,  'Caddyshack', '1980-07-25', 7.2,
 'A scrappy golf-club comedy built from loosely connected sketches. Murray''s gopher-hunting groundskeeper is gloriously unhinged. Uneven, but the best bits are legendary.'),
(6,  'Stripes', '1981-06-26', 6.9,
 'Two slackers join the army and accidentally become heroes. Murray''s laid-back charm carries a loose, goofy plot. Dated in places, but the training montage and sly humour still land.'),
(7,  'Scrooged', '1988-11-23', 6.5,
 'A modern, ruthless TV executive gets the Dickensian ghost treatment. Murray is hilariously abrasive, though the frantic tone sometimes wobbles before a sentimental finish.'),
(8,  'The Royal Tenenbaums', '2001-12-14', 8.0,
 'A dysfunctional family of former prodigies reunites in a meticulously designed New York. Funny, sad and gorgeous to look at, with a superb ensemble including Murray as a stuffy neurologist.'),
(9,  'Zombieland', '2009-10-02', 7.6,
 'Four survivors roam a zombie-ravaged America following a list of survival rules. Fast, funny and gory, with a legendary Murray cameo that is worth the price of admission alone.'),
(10, 'Broken Flowers', '2005-08-05', 7.4,
 'A deadpan ageing bachelor visits old flames after receiving an anonymous letter. Jim Jarmusch''s slow road movie is anchored by Murray''s masterfully minimal performance.'),
(11, 'The Godfather', '1972-03-24', 9.8,
 'Coppola''s crime epic traces the transformation of Michael Corleone from reluctant outsider to ruthless boss. Flawless performances, rich cinematography and a story of power and family that still defines great cinema.'),
(12, 'Pulp Fiction', '1994-10-14', 9.0,
 'Tarantino''s interlocking tales of hitmen, boxers and gangsters crackle with razor-sharp dialogue and dark humour. Its fractured structure and killer soundtrack reshaped independent cinema.'),
(13, 'Alien', '1979-05-25', 9.0,
 'A commercial crew is hunted by a perfect organism aboard a cramped spaceship. Ridley Scott builds suffocating dread with patience, and Sigourney Weaver makes Ripley an icon.'),
(14, 'Spirited Away', '2001-07-20', 9.3,
 'A young girl must work in a bathhouse for spirits to free her parents. Miyazaki''s imagination is boundless, delivering a visually stunning, emotional and endlessly inventive fantasy.'),
(15, 'Parasite', '2019-05-30', 9.2,
 'A poor family infiltrates a wealthy household in Bong Joon-ho''s razor-sharp class thriller. It shifts effortlessly from comedy to horror to tragedy, and every frame is meticulously designed.'),
(16, 'Blade Runner', '1982-06-25', 8.6,
 'Ridley Scott''s rain-soaked future noir asks what it means to be human. Slow and moody, but the world-building, Vangelis score and haunting final scene are unforgettable.'),
(17, 'The Shawshank Redemption', '1994-09-23', 9.5,
 'A banker wrongly imprisoned for murder finds hope and friendship behind bars. Patient, humane storytelling and superb performances from Tim Robbins and Morgan Freeman make it deeply uplifting.'),
(18, 'Jaws', '1975-06-20', 8.8,
 'A great white terrorises a New England beach town. Spielberg wrings tension from what he hides, and the sharp character work and John Williams score make it the original blockbuster.'),
(19, 'Back to the Future', '1985-07-03', 9.0,
 'A teenager accidentally travels to 1955 and must reunite his parents. A perfectly constructed script, great chemistry between Michael J. Fox and Christopher Lloyd, and sheer joy throughout.'),
(20, 'Mad Max: Fury Road', '2015-05-15', 8.7,
 'A relentless desert chase powered by practical stunts and astonishing design. George Miller delivers pure kinetic cinema, with Charlize Theron''s Furiosa as the true heart of the film.'),
(21, 'Casablanca', '1942-11-26', 9.2,
 'A cynical nightclub owner in wartime Morocco must choose between love and duty. Bogart and Bergman sizzle, the dialogue is endlessly quotable, and its romance still feels timeless.'),
(22, 'Toy Story', '1995-11-22', 9.0,
 'Woody and Buzz Lightyear learn to be friends in the first fully computer-animated feature. Witty, warm and inventive, it holds up as both a technical landmark and a great story.'),
(23, 'The Matrix', '1999-03-31', 8.7,
 'A hacker discovers reality is a simulation. Groundbreaking action, bullet-time effects and heady ideas combine into a thrilling sci-fi that changed how action films look.'),
(24, 'Whiplash', '2014-10-10', 8.9,
 'A young drummer faces a terrifying conservatory teacher. J.K. Simmons is ferocious, the editing is propulsive, and the finale is one of the most electrifying sequences in modern film.'),
(25, 'Moonlight', '2016-10-21', 8.6,
 'Three chapters follow a young Black man growing up in Miami and discovering who he is. Barry Jenkins crafts a tender, beautifully shot and quietly devastating portrait of identity.'),
(26, 'The Grand Budapest Hotel', '2014-03-07', 8.4,
 'A legendary concierge and his lobby boy get caught up in a caper involving a stolen painting. Wes Anderson''s symmetrical, colourful world is packed with wit and melancholy.'),
(27, 'Everything Everywhere All at Once', '2022-03-25', 8.5,
 'A overwhelmed laundromat owner jumps across the multiverse to save her family. Wildly inventive, hilarious and surprisingly moving, anchored by a tour-de-force Michelle Yeoh.'),
(28, 'Spider-Man: Into the Spider-Verse', '2018-12-14', 8.7,
 'Miles Morales becomes Spider-Man alongside heroes from other dimensions. The comic-book animation style is groundbreaking, and the film is funny, heartfelt and endlessly stylish.'),
(29, 'The General', '1926-12-31', 8.2, 'The film sees a railway engineer chase a stolen locomotive across Civil War lines. An outstanding comedy that rewards close attention. The visuals is particularly impressive. Highly recommended.'),
